#version 330
#extension GL_ARB_separate_shader_objects : require

// Full-screen triangle for post passes: the same as vanilla core/screenquad (26.3) and
// core/screentriangle (26.4), shipped with the pack so it does not depend on either.
layout(location = 0) out vec2 texCoord;

void main() {
    vec2 uv = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
    gl_Position = vec4(uv * 2.0 - 1.0, 0.0, 1.0);
    texCoord = uv;
}

#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;

layout(std140) uniform SamplerInfo {
    vec2 OutSize;
    vec2 InSize;
};

layout(std140) uniform OutlineConfig {
    vec4 Tint;
    float Radius;
};

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    // minecraft:entity_outline holds the silhouettes of glowing entities: team color in rgb, coverage in alpha.
    if (texture(InSampler, texCoord).a > 0.0) {
        fragColor = vec4(0.0);       // inside the silhouette: no outline
        return;
    }
    // Outside: outline if any silhouette pixel is within Radius pixels (a disc).
    int r = int(Radius);
    for (int y = -r; y <= r; y++) {
        for (int x = -r; x <= r; x++) {
            if (x * x + y * y > r * r) {
                continue;
            }
            vec4 near = texture(InSampler, texCoord + vec2(x, y) / InSize);
            if (near.a > 0.0) {
                fragColor = vec4(near.rgb * Tint.rgb, 1.0);
                return;
            }
        }
    }
    fragColor = vec4(0.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    // Keep alpha: the game composites minecraft:entity_outline onto the world by its alpha.
    fragColor = texture(InSampler, texCoord);
}
